  "bbdata.toneExample.low.low": { en: "\"Notice: due to maintenance of our internal facilities, our store will close early today at 5:00 PM. We apologize for any inconvenience.\"", id: "\"Pemberitahuan. Sehubungan dengan perbaikan fasilitas internal, operasional toko kami hari ini ditutup lebih awal pukul 17.00 WIB. Mohon maaf atas ketidaknyamanan yang ditimbulkan.\"" },
  "bbdata.toneExample.low.mid": { en: "\"Dear valued customers, we apologize that our store will close early today at 5:00 PM due to repairs. Thank you for your understanding.\"", id: "\"Kepada pelanggan yang terhormat, mohon maaf toko kami tutup lebih awal hari ini pukul 17.00 karena ada perbaikan. Terima kasih atas pengertiannya.\"" },
  "bbdata.toneExample.low.high": { en: "\"We're closing a little early today, at 5 PM, for some facility repairs. Sorry for the inconvenience — see you tomorrow!\"", id: "\"Hari ini kami tutup sedikit lebih awal, jam 5 sore, karena ada perbaikan fasilitas. Mohon maaf atas ketidaknyamanannya, sampai jumpa besok!\"" },
  "bbdata.toneExample.mid.low": { en: "\"Hello, sorry — the store is closing early today (5 PM) due to internal repairs. Thanks for understanding.\"", id: "\"Halo, mohon maaf toko tutup lebih awal hari ini (jam 5 sore) karena ada perbaikan internal. Terima kasih sudah memahami.\"" },
  "bbdata.toneExample.mid.mid": { en: "\"Hi, we're closing early today at 5 PM — doing a bit of renovating. Thanks for understanding!\"", id: "\"Hai, hari ini kita tutup lebih awal ya jam 5 sore — lagi renovasi dikit. Makasih pengertiannya!\"" },
  "bbdata.toneExample.mid.high": { en: "\"Hey! We're heading out early today at 5 PM because we're giving the shop a little tidy-up. Thanks for getting it — see you tomorrow!\"", id: "\"Hai! Hari ini kita cabut lebih cepat jam 5 sore soalnya lagi beberes toko. Makasih ya udah ngertiin, sampai besok!\"" },
  "bbdata.toneExample.high.low": { en: "\"Hi, so sorry — the shop's closing early today at 5 PM for repairs. Thanks for understanding.\"", id: "\"Halo, mohon maaf ya, tokonya tutup lebih awal hari ini jam 5 sore karena ada perbaikan. Makasih sudah mengerti.\"" },
  "bbdata.toneExample.high.mid": { en: "\"Hey everyone, we're closing at 5 PM today — doing a little renovating to make it even comfier. Thanks for understanding!\"", id: "\"Gais, hari ini mimin tutup jam 5 sore ya, lagi renovasi dikit biar makin nyaman. Makasih pengertiannya!\"" },
  "bbdata.toneExample.high.high": { en: "\"Hey guys, so sorry! We have to close up shop at 5 PM today — the floor's getting a makeover so it looks extra aesthetic when you hang out tomorrow. See you tomorrow with a fresh new look!\"", id: "\"Gais, maaf banget ya! Hari ini mimin terpaksa tutup warung jam 5 sore nih, soalnya lantai toko mau divermak dulu biar makin estetik pas kamu nongkrong besok. Sampai ketemu besok dengan wajah baru, ya!\"" },

