  "bg.book.specimen.primaryDesc": { en: "This font is used for titles and elements that need attention first — headlines, product names, big CTAs. Bold, clear and readable from a distance.", id: "Font ini dipakai untuk judul dan elemen yang butuh perhatian pertama — headline, nama produk, CTA besar. Tegas, jelas, dan langsung kebaca dari jarak jauh." },
  "bg.book.specimen.secondaryDesc": { en: "This font was chosen because it reads well in long text — descriptions, articles, captions. Its clean design stays comfortable to read for a long time without tiring the eyes.", id: "Font ini dipilih karena keterbacaannya bagus untuk teks panjang — deskripsi, artikel, caption. Desainnya bersih dan nyaman dibaca berlama-lama tanpa bikin capek mata." },
  "bg.book.specimen.accentDesc": { en: "This font is used sparingly — for highlights, quotes or small decorative elements that need a different character from the main text. Don't use it for long body text.", id: "Font ini dipakai terbatas — buat highlight, quote, atau elemen dekoratif kecil yang butuh karakter beda dari teks utama. Jangan dipakai buat body text panjang." },
  "bg.book.specimen.extraDesc": { en: "An extra font, \"{label}\" — used as a visual flourish when the design calls for it, not for main text.", id: "Font tambahan \"{label}\" — dipakai sebagai pemanis visual sesuai kebutuhan desain, bukan untuk teks utama." },
